begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(1);
create temporary table cash_policy_fixture as select gen_random_uuid() owner_id, gen_random_uuid() other_id;
grant select on cash_policy_fixture to authenticated;
insert into auth.users (id,email,encrypted_password,aud,role,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select owner_id,'cash-policy-owner@example.invalid','x','authenticated','authenticated',now(),'{}'::jsonb,'{}'::jsonb,now(),now() from cash_policy_fixture
union all select other_id,'cash-policy-other@example.invalid','x','authenticated','authenticated',now(),'{}'::jsonb,'{}'::jsonb,now(),now() from cash_policy_fixture;
select set_config('request.jwt.claim.sub',owner_id::text,true),set_config('request.jwt.claim.role','authenticated',true) from cash_policy_fixture;
set local role authenticated;
do $$
declare s uuid; loc uuid; branch uuid; member uuid; customer uuid; service uuid;
 invoice uuid; session uuid; req uuid; issue_req uuid; pay_req uuid; result uuid;
 paid timestamptz := now(); method public.payment_method; stage integer; command integer;
 blocked boolean; must_block boolean; required boolean; payment uuid; allocation uuid;
 refund_req uuid := gen_random_uuid(); dashboard jsonb;
 completed_invoice uuid; completed_req uuid; completed_issue_req uuid; completed_pay_req uuid;
begin
 s := public.create_owner_shop('Cash policy fixture','multi','service');
 select id into loc from public.shop_locations where shop_id=s and is_default;
 branch := public.save_shop_location(s,null,'Other branch','OTHER',null,null);
 select id into member from public.shop_memberships where shop_id=s and role='owner';
 customer := public.save_customer(s,null,'Policy customer',null,null,null,null);
 service := public.save_service(s,null,'Policy service',null,70,'amount',0);
 if public.shop_cash_policy(s) then raise exception 'new Shop policy must default OFF'; end if;
 begin
   update public.shops set require_open_cash_shift=true where id=s;
   raise exception 'direct policy update allowed';
 exception when insufficient_privilege then null; end;
 begin
   perform public.set_shop_cash_policy(s,null);
   raise exception 'null policy allowed';
 exception when invalid_parameter_value then null; end;
 -- Every authoritative path: both methods, OFF/ON, wrong/open/closed location.
 for stage in 0..5 loop
   required := stage between 1 and 4;
   perform public.set_shop_cash_policy(s,required);
   perform public.set_shop_cash_policy(s,required);
   if stage=2 then perform public.open_cash_shift(gen_random_uuid(),s,branch,'main',0,null); end if;
   if stage=3 then session := public.open_cash_shift(gen_random_uuid(),s,loc,'main',100,null); end if;
   if stage=4 then
     dashboard := public.cash_shift_dashboard(s,loc,null,1,20);
     perform public.close_cash_shift(gen_random_uuid(),s,session,(dashboard #>> '{active,expectedCash}')::numeric,null);
     perform public.checkout_pos_sale(completed_req,completed_issue_req,completed_pay_req,null,
       s,loc,completed_invoice,70,paid,'card',null); -- completed retry after close
   end if;
   must_block := stage in (1,2,4);
   foreach method in array array['cash','card']::public.payment_method[] loop
     for command in 0..7 loop
       -- Issue receipt fixtures with policy OFF to isolate the payment guard.
       if command in (6,7) then perform public.set_shop_cash_policy(s,false); end if;
       invoice := public.save_pos_sale_draft(gen_random_uuid(),s,loc,null,member,null,
         case when command in (2,3,5) then null else customer end,null,
         jsonb_build_array(jsonb_build_object('item_type','service','source_id',service,'quantity',1)));
       invoice := public.save_pos_sale_draft(gen_random_uuid(),s,loc,invoice,member,null,
         case when command in (2,3,5) then null else customer end,'Edited draft',
         jsonb_build_array(jsonb_build_object('item_type','service','source_id',service,'quantity',1)));
       if command in (6,7) then
         perform public.issue_location_sale(gen_random_uuid(),s,loc,invoice);
         perform public.set_shop_cash_policy(s,required);
       end if;
       req := gen_random_uuid(); issue_req := gen_random_uuid(); pay_req := gen_random_uuid(); blocked := false;
       begin
         for retry in 1..2 loop
           case command
             when 0 then result := public.issue_sale(req,s,invoice);
             when 1 then result := public.issue_location_sale(req,s,loc,invoice);
             when 2 then result := public.checkout_customerless_sale(req,s,invoice,70,paid,method,null);
             when 3 then result := public.checkout_location_sale(req,s,loc,invoice,70,paid,method,null);
             when 4,5 then result := public.checkout_pos_sale(req,issue_req,pay_req,null,s,loc,invoice,70,paid,method,null);
             when 6 then result := public.record_customer_receipt(req,s,customer,70,paid,method,null,null,
               jsonb_build_array(jsonb_build_object('invoice_id',invoice,'amount',70)));
             when 7 then result := public.record_location_customer_receipt(req,s,loc,customer,70,paid,method,null,null,
               jsonb_build_array(jsonb_build_object('invoice_id',invoice,'amount',70)));
           end case;
         end loop;
       exception when check_violation then
         if sqlerrm <> 'SALE_OPEN_CASH_SHIFT_REQUIRED' then raise; end if;
         blocked := true;
       end;
       if blocked <> must_block then raise exception 'policy mismatch stage %, command %, method %',stage,command,method; end if;
       if blocked and command < 6 and (select status from public.invoices where id=invoice) <> 'draft' then raise exception 'blocked checkout changed draft'; end if;
       if blocked and exists(select 1 from public.payments where invoice_id=invoice) then raise exception 'blocked checkout wrote payment'; end if;
       if stage=3 and command=5 and method='card' then
         completed_invoice := invoice; completed_req := req;
         completed_issue_req := issue_req; completed_pay_req := pay_req;
       end if;
       if stage=3 and command=4 and method='cash' then
         select id into payment from public.payments where invoice_id=invoice and customer_kind='receipt';
         select id into allocation from public.customer_payment_allocations where payment_id=payment;
         for retry in 1..2 loop
           perform public.refund_customer_receipt(refund_req,s,payment,paid,'cash',null,'Policy refund',
             jsonb_build_array(jsonb_build_object('allocation_id',allocation,'amount',20)));
         end loop;
       end if;
     end loop;
   end loop;
   if stage=3 then
     dashboard := public.cash_shift_dashboard(s,loc,null,1,20);
     if (dashboard #>> '{active,expectedCash}')::numeric <> 500
       or (dashboard #>> '{active,cashSales}')::numeric <> 420
       or (dashboard #>> '{active,cashRefunds}')::numeric <> 20
       or jsonb_array_length(dashboard #> '{active,events}') <> 7 then
       raise exception 'drawer exactly-once/non-cash invariant failed: %',dashboard;
     end if;
   end if;
 end loop;
 perform set_config('cash_policy.shop',s::text,true);
end;
$$;
reset role;
do $$
declare s uuid := current_setting('cash_policy.shop')::uuid;
begin
 if exists(select 1 from public.shop_cash_policy_changes where shop_id=s and (previous_required=new_required or changed_by_profile_id is null or changed_at is null))
   or not exists(select 1 from public.shop_cash_policy_changes where shop_id=s and new_required)
   or not exists(select 1 from public.shop_cash_policy_changes where shop_id=s and not new_required) then raise exception 'missing/invalid audit'; end if;
 begin
   update public.shop_cash_policy_changes set changed_at=now() where shop_id=s;
   raise exception 'audit mutable';
 exception when object_not_in_prerequisite_state then
   if sqlerrm <> 'CASH_POLICY_AUDIT_IMMUTABLE' then raise; end if;
 end;
 if has_function_privilege('anon','public.set_shop_cash_policy(uuid,boolean)','execute')
   or has_function_privilege('authenticated','shop_private.assert_sale_cash_shift(uuid,uuid)','execute') then raise exception 'unsafe policy privilege'; end if;
end;
$$;
select set_config('request.jwt.claim.sub',other_id::text,true) from cash_policy_fixture;
set local role authenticated;
do $$
begin
 begin
   perform public.set_shop_cash_policy(current_setting('cash_policy.shop')::uuid,true);
   raise exception 'other tenant changed policy';
 exception when insufficient_privilege then null; end;
 begin
   perform public.shop_cash_policy(current_setting('cash_policy.shop')::uuid);
   raise exception 'other tenant read policy';
 exception when insufficient_privilege then null; end;
 if exists(select 1 from public.shop_cash_policy_changes where shop_id=current_setting('cash_policy.shop')::uuid) then raise exception 'other tenant read audit'; end if;
end;
$$;
reset role;
-- Create an active member without settings permission, then delegate the
-- existing manager role. Fixture administration never represents a browser write.
insert into public.profiles (user_id,portal_id,display_name,email_snapshot)
select fixture.other_id,shop.portal_id,'Policy member','cash-policy-other@example.invalid'
from cash_policy_fixture fixture join public.shops shop on shop.id=current_setting('cash_policy.shop')::uuid;
insert into public.shop_memberships (shop_id,profile_id,role,status)
select current_setting('cash_policy.shop')::uuid,profile.id,'employee','active'
from public.profiles profile join cash_policy_fixture fixture on fixture.other_id=profile.user_id;
insert into public.membership_roles (membership_id,role_id)
select membership.id,role.id from public.shop_memberships membership
join public.profiles profile on profile.id=membership.profile_id
join cash_policy_fixture fixture on fixture.other_id=profile.user_id
join public.roles role on role.shop_id=membership.shop_id and role.key='cashier'
where membership.shop_id=current_setting('cash_policy.shop')::uuid;
set local role authenticated;
do $$
begin
 begin
   perform public.set_shop_cash_policy(current_setting('cash_policy.shop')::uuid,true);
   raise exception 'cashier changed policy';
 exception when insufficient_privilege then null; end;
 if exists(select 1 from public.shop_cash_policy_changes where shop_id=current_setting('cash_policy.shop')::uuid) then
   raise exception 'cashier read settings audit';
 end if;
end;
$$;
reset role;
update public.membership_roles assignment set role_id=role.id
from public.roles role,public.shop_memberships membership,public.profiles profile,cash_policy_fixture fixture
where assignment.membership_id=membership.id and membership.profile_id=profile.id
 and profile.user_id=fixture.other_id and membership.shop_id=current_setting('cash_policy.shop')::uuid
 and role.shop_id=membership.shop_id and role.key='manager';
set local role authenticated;
select public.set_shop_cash_policy(current_setting('cash_policy.shop')::uuid,true);
select public.set_shop_cash_policy(current_setting('cash_policy.shop')::uuid,true);
reset role;
do $$
begin
 if (select count(*) from public.shop_cash_policy_changes change
   join public.profiles profile on profile.id=change.changed_by_profile_id
   join cash_policy_fixture fixture on fixture.other_id=profile.user_id
   where change.shop_id=current_setting('cash_policy.shop')::uuid) <> 1 then
   raise exception 'delegated manager change/retry audit incorrect';
 end if;
end;
$$;
update public.shop_memberships membership set status='suspended'
from public.profiles profile,cash_policy_fixture fixture
where membership.profile_id=profile.id and profile.user_id=fixture.other_id
 and membership.shop_id=current_setting('cash_policy.shop')::uuid;
set local role authenticated;
do $$
begin
 begin
   perform public.set_shop_cash_policy(current_setting('cash_policy.shop')::uuid,false);
   raise exception 'suspended manager changed policy';
 exception when insufficient_privilege then null; end;
end;
$$;
reset role;
select pass('Cash policy command matrix, authorization, compatibility, audit and drawer invariants');
select * from finish();
rollback;

import { expect, type Page, type Route } from '@playwright/test'
import { createServer } from 'node:http'


// SSR controls are visible before Vue has attached event handlers.
export async function fixtureGoto(page: Page, url: string) {
  await page.goto(url)
  await fixtureMounted(page)
}
export async function fixtureReload(page: Page) {
  await page.reload()
  await fixtureMounted(page)
}
async function fixtureMounted(page: Page) {
  await page.waitForFunction(() => Boolean((document.getElementById('__nuxt') as HTMLElement & { __vue_app__?: unknown })?.__vue_app__))
}

// Both transports execute the same synthetic fixture handlers, including test
// overrides. Authenticated SSR must not contact a real disposable database.
const transports = new WeakMap<Page, { routes: Array<{ pattern: string | RegExp; handler: (route: Route) => unknown }> }>()
export async function fixtureRoute(page: Page, pattern: string | RegExp, handler: (route: Route) => unknown) {
  transports.get(page)!.routes.push({ pattern, handler })
  await page.route(pattern, handler)
}
export async function fixtureUnroute(page: Page, pattern: string | RegExp) {
  const transport = transports.get(page)!
  transport.routes = transport.routes.filter(item => item.pattern !== pattern)
  await page.unroute(pattern)
}
async function fixtureTransport(page: Page) {
  const transport = { routes: [] as Array<{ pattern: string | RegExp; handler: (route: Route) => unknown }> }
  transports.set(page, transport)
  const server = createServer(async (request, response) => {
    let body = ''; for await (const chunk of request) body += chunk
    const url = 'http://127.0.0.1:46421' + request.url
    const matches = [...transport.routes].reverse().filter(({ pattern }) => typeof pattern === 'string' ? url.endsWith(pattern.replace(/^\*\*/, '')) : pattern.test(url))
    const dispatch = async (index = 0): Promise<void> => {
      const handler = matches[index]?.handler
      if (!handler) { response.writeHead(501); response.end('Unregistered synthetic fixture'); return }
      const route = {
        request: () => ({ url: () => url, postDataJSON: () => body ? JSON.parse(body) : null }),
        fulfill: async (value: { status?: number; json: unknown }) => { response.writeHead(value.status ?? 200, { 'content-type': 'application/json' }); response.end(JSON.stringify(value.json)) },
        fallback: () => dispatch(index + 1),
      } as unknown as Route
      await handler(route)
    }
    try { await dispatch() } catch { if (!response.headersSent) response.writeHead(500); response.end('Synthetic fixture handler failed') }
  })
  await new Promise<void>(resolve => server.listen(0, '127.0.0.1', resolve))
  page.on('close', () => server.close())
  return (server.address() as { port: number }).port
}

// Synthetic responses only: this suite never connects to a database.
export async function pilotFixture(page: Page, locale: string, role = 'owner', override?: (name: string, args: Record<string, unknown>) => unknown | Promise<unknown>) {
  const fixturePort = await fixtureTransport(page)
  const calls: Array<{ name: string; args: Record<string, unknown> }> = []
  const state = { calendarError: false, calendarDenied: false, delayCalendar: false, emptyCalendar: false, failAccess: false }
  const user = { id: '00000000-0000-4000-8000-000000000001', email: 'pilot@example.test', aud: 'authenticated', role: 'authenticated', app_metadata: {}, user_metadata: {} }
  const jwt = `${Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })).toString('base64url')}.${Buffer.from(JSON.stringify({ sub: user.id, exp: Math.floor(Date.now() / 1000) + 3600, role: 'authenticated', fixture_role: role, fixture_port: fixturePort, email: user.email })).toString('base64url')}.test`
  const locations = ['First branch', 'Second branch'].map((name, index) => ({ id: `location-${index + 1}`, shop_id: 'shop-1', name, status: 'active', is_default: index === 0 }))
  const staff = { membershipId: 'membership-1', name: 'Pilot barber', locationIds: locations.map(item => item.id) }
  const service = { id: 'service-1', name: 'Haircut', itemType: 'service', unitPrice: 100, discount: 0, stock: null, sku: null, barcode: null }
  const start = new Date(); start.setHours(10, 0, 0, 0)
  const appointment = (locationId: string, name = 'Booked customer') => ({ id: `appointment-${locationId}`, locationId, staffMembershipId: staff.membershipId, serviceId: service.id, customerId: null, identityKind: 'walk_in', customerName: name, status: 'arrived', startsAt: start.toISOString(), endsAt: new Date(start.getTime() + 1800000).toISOString(), serviceName: service.name, staffName: staff.name, saleId: null, history: [] })
  const appointments = locations.map(location => appointment(location.id))
  await fixtureRoute(page, /^http:\/\/127\.0\.0\.1:(?:61321|46421)\//, async route => {
    const url = new URL(route.request().url())
    if (url.pathname.includes('/auth/v1/')) {
      await route.fulfill({ json: url.pathname.endsWith('/token') ? { access_token: jwt, refresh_token: 'test', expires_in: 3600, token_type: 'bearer', user } : user }); return
    }
    const name = url.pathname.split('/').at(-1)!
    const args = route.request().postDataJSON() ?? {}
    calls.push({ name, args })
    if (name === 'appointment_calendar') {
      if (state.delayCalendar) await new Promise(resolve => setTimeout(resolve, 700))
      if (state.calendarError || state.calendarDenied) {
        await route.fulfill({ status: state.calendarDenied ? 403 : 500, json: { message: state.calendarDenied ? 'SHOP_PERMISSION_DENIED' : 'temporarily unavailable' } }); return
      }
    }
    if (name === 'shop_permission_access' && state.failAccess) {
      await route.fulfill({ status: 500, json: { message: 'temporarily unavailable' } }); return
    }
    const overridden = await override?.(name, args)
    if (overridden !== undefined) { await route.fulfill({ json: overridden }); return }
    let data: unknown = []
    switch (name) {
      case 'portals': data = { id: 'portal-1' }; break
      case 'profiles': data = { id: 'profile-1', status: 'active' }; break
      case 'shop_memberships': data = [{ id: staff.membershipId, shop_id: 'shop-1', profile_id: 'profile-1', role, status: 'active' }]; break
      case 'shops': data = [{ id: 'shop-1', name: 'Pilot shop', business_mode: 'service', status: 'active', created_at: '2026-01-01' }]; break
      case 'list_shop_locations': data = locations; break
      case 'receipt_settings': data = { displayName: 'Pilot shop', address: null, phone: null, footer: null, paperSize: 'thermal_80', canManage: role === 'owner' }; break
      case 'shop_plan_usage': data = { resources: [] }; break
      case 'subscriptions': data = { status: 'trialing', trial_end_at: '2026-10-10', plan_id: 'plan-1' }; break
      case 'shop_permission_access': data = { 'reports.view': false }; break
      case 'appointment_options': data = { canManage: true, canManageSchedule: role !== 'barber', locations, staff: [staff], services: [{ ...service, durationMinutes: 30, cleanupMinutes: 0, locationIds: staff.locationIds, staffMembershipIds: [staff.membershipId] }], customers: [] }; break
      case 'appointment_calendar': data = { appointments: state.emptyCalendar ? [] : appointments.filter(item => item.locationId === args.p_location_id), workingHours: [], blocks: [] }; break
      case 'save_appointment': {
        await new Promise(resolve => setTimeout(resolve, 500))
        const created = { ...appointment(String(args.p_location_id), String(args.p_walk_in_name)), id: 'new-appointment', startsAt: String(args.p_starts_at) }
        appointments.push(created); data = created.id; break
      }
      case 'pos_catalog_search':
      case 'pos_catalog_search_by_category': data = { items: [service], total: 1, page: 1, pageSize: 30, businessMode: 'service', ambiguousBarcode: false }; break
      case 'pos_checkout_context': data = { staff: [{ id: staff.membershipId, name: staff.name }], customers: [], appointments: appointments.filter(item => item.locationId === args.p_location_id).map(item => ({ ...item, staffId: staff.membershipId, service })) }; break
      case 'save_pos_sale_draft': data = 'sale-1'; break
      case 'checkout_pos_sale': data = 'sale-1'; break
      case 'get_location_sale_receipt': data = {
        version: 1,
        invoiceId: 'sale-1',
        invoiceNumber: 'SALE-1',
        issuedAt: start.toISOString(),
        currency: 'EGP',
        business: { name: 'Pilot shop', address: null, phone: null },
        location: { ...locations.find(item => item.id === args.p_location_id), code: null, address: null, phone: null },
        staffName: staff.name,
        customer: { name: 'Booked customer', phone: null },
        lines: [{ id: 'line-1', itemType: 'service', name: service.name, sku: null, quantity: 1, unitPrice: 100, discount: 0, total: 100 }],
        payments: [{ id: 'payment-1', amount: 100, method: 'cash', reference: null, paidAt: start.toISOString() }],
        subtotal: 100,
        discount: 0,
        total: 100,
        footer: null,
        paperSize: 'thermal_80',
      }; break
      case 'shop_billing_read': data = { subscription: { planName: 'Pilot plan', accessState: 'trialing', priceAmount: 100, currency: 'EGP', trialDaysRemaining: 7 }, instructions: { recipientAlias: 'pilot-billing-account-with-a-long-alias@example.test', instructionsEn: 'Review the reference before sending.', instructionsAr: 'راجع المرجع قبل الإرسال.' }, usage: { locations: 1, products: 0, services: 1, members: 2, limits: {}, resources: [] }, submissions: [] }; break
      case 'platform_admin_session': data = { userId: user.id, role: 'observer', canMutate: false }; break
      case 'platform_admin_read': data = args.p_resource === 'dashboard' ? { shops: 1, locations: 2, members: 2, recentEvents: [] } : { items: [], total: 0 }; break
      case 'platform_admin_billing_read': data = { items: [], total: 0, open: 0 }; break
    }
    await route.fulfill({ json: data })
  })
  await page.context().addCookies([{ name: 'building-suit-locale', value: locale, domain: '127.0.0.1', path: '/' }])
  await page.goto('/auth/login')
  await expect(page).toHaveURL(/\/auth\/login(?:[?#]|$)/)

  // SSR-visible controls are not sufficient: wait until Vue has mounted
  // and the form submit handler is attached before interacting.
  const loginForm = page.locator('form')
  const emailInput = page.locator('#login-email')
  const passwordInput = page.locator('#login-password')
  const submitButton = page.locator('form button[type="submit"]')

  await expect(loginForm).toHaveAttribute(
    'data-client-ready',
    'true',
    { timeout: 30_000 },
  )
  await expect(emailInput).toBeVisible()
  await expect(passwordInput).toBeVisible()
  await expect(submitButton).toBeEnabled()

  await emailInput.fill(user.email)
  await passwordInput.fill('fixture-password')
  await submitButton.click()
  await expect(page).toHaveURL(/dashboard/, { timeout: 20_000 })
  await expect(page.getByRole('main').getByRole('heading', {
    name: locale === 'ar' ? 'لوحة التحكم' : 'Operating dashboard',
    exact: true,
  })).toBeVisible({ timeout: 20_000 })
  return { calls, state }
}

// Disposable verifier transport for authenticated Nuxt SSR and browser reloads.
// Synthetic identity/data only; never forwards requests to a Supabase project.
import {createServer} from 'node:http'
import {spawn} from 'node:child_process'
import {fileURLToPath} from 'node:url'
import path from 'node:path'
const userId='00000000-0000-4000-8000-000000000001'
const user={id:userId,email:'pilot@example.test',aud:'authenticated',role:'authenticated',app_metadata:{},user_metadata:{}}
export async function fixtureResponse(url,authorization,request){
 let claims
 try{const token=String(authorization??'').replace(/^Bearer /,'');if(!token.endsWith('.test'))throw Error('not synthetic');claims=JSON.parse(Buffer.from(token.split('.')[1],'base64url'))}catch{return {status:401,data:{message:'Synthetic fixture session required'}}}
 if(claims.sub!==userId)return {status:401,data:{message:'Synthetic fixture identity required'}}
 if(url.pathname==='/auth/v1/user')return {status:200,data:user}
 const port=Number(claims.fixture_port)
 if(!Number.isInteger(port)||port<1024||port>65535||[4326,46421].includes(port))return {status:401,data:{message:'Synthetic fixture transport required'}}
 const body=[];for await(const chunk of request)body.push(chunk)
 const response=await fetch('http://127.0.0.1:'+port+url.pathname+url.search,{method:request.method,headers:{'content-type':'application/json'},body:['GET','HEAD'].includes(request.method)?undefined:Buffer.concat(body)})
 return {status:response.status,data:await response.json()}
}
if(process.argv[1]===fileURLToPath(import.meta.url)){
 const api=createServer(async(req,res)=>{
  const url=new URL(req.url,'http://127.0.0.1:46421')
  const value=url.pathname==='/fixture-ready'?{status:200,data:{synthetic:true}}:await fixtureResponse(url,req.headers.authorization,req)
  res.writeHead(value.status,{'content-type':'application/json'});res.end(JSON.stringify(value.data))
 })
 api.listen(46421,'127.0.0.1',()=>{
  const app=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../../.output/server/index.mjs')
  const child=spawn(process.execPath,[app],{stdio:'inherit',env:{...process.env,HOST:'127.0.0.1',PORT:'4326',NUXT_PUBLIC_SUPABASE_URL:'http://127.0.0.1:46421',SUPABASE_URL:'http://127.0.0.1:46421'}})
  for(const signal of ['SIGTERM','SIGINT'])process.on(signal,()=>{child.kill(signal);api.close()})
  child.on('exit',code=>{api.close();process.exitCode=code??1})
 })
}

import { expect, test } from '@playwright/test'
import { pilotFixture, fixtureRoute, fixtureUnroute, fixtureGoto, fixtureReload } from './pilot-fixture'

// Browser tests use synthetic HTTP responses; authoritative policy/financial
// invariants are exercised separately by the task's database command matrix.
for (const locale of ['en', 'ar']) {
  const ar = locale === 'ar'
  for (const mobile of [false, true]) for (const theme of ['light', 'dark']) {
    test(`Business cashier policy ${locale} ${mobile ? 'mobile' : 'desktop'} ${theme}`, async ({ page }) => {
      await page.setViewportSize({ width: mobile ? 390 : 1440, height: 900 })
      await page.addInitScript(value => localStorage.setItem('building-suit.theme', value), theme)
      let required = false
      const { calls } = await pilotFixture(page, locale, 'owner', (name, args) => {
        if (name === 'shop_permission_access') return { 'settings.manage': true }
        if (name === 'shop_cash_policy') return required
        if (name === 'set_shop_cash_policy') { required = args.p_required === true; return required }
        return undefined
      })
      await fixtureGoto(page, '/settings')
      const toggle = page.getByRole('checkbox', { name: ar ? 'اشتراط وردية خزنة مفتوحة للمبيعات' : 'Require an open cashier shift for sales' })
      const save = page.getByRole('button', { name: ar ? 'حفظ سياسة الخزنة' : 'Save cashier policy', exact: true })
      await expect(toggle).not.toBeChecked()
      await expect(save).toBeDisabled()
      await toggle.focus()
      await expect(toggle).toBeFocused()
      await page.keyboard.press('Space')
      await save.click()
      await expect(page.getByRole('status').filter({ hasText: ar ? 'اتحفظت سياسة ورديات الخزنة.' : 'Cashier shift policy saved.' })).toBeVisible()
      expect(calls.filter(call => call.name === 'set_shop_cash_policy').at(-1)?.args).toEqual({ p_shop_id: 'shop-1', p_required: true })
      await fixtureReload(page)
      await expect(toggle).toBeChecked()
      await page.screenshot({ path: test.info().outputPath('policy-enabled.png'), fullPage: true })
      expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true)
      await toggle.uncheck()
      await save.click()
      await expect(save).toBeDisabled()
      expect(required).toBe(false)
    })
  }

  test(`Policy load failure, retry, save failure and denied ${locale}`, async ({ page }) => {
    await pilotFixture(page, locale, 'cashier', name => {
      if (name === 'shop_cash_policy') return false
      if (name === 'shop_permission_access') return { 'settings.manage': false }
      return undefined
    })
    await fixtureGoto(page, '/settings')
    const toggle = page.getByRole('checkbox', { name: ar ? 'اشتراط وردية خزنة مفتوحة للمبيعات' : 'Require an open cashier shift for sales' })
    await expect(toggle).toBeDisabled()
    await expect(page.getByRole('button', { name: ar ? 'حفظ سياسة الخزنة' : 'Save cashier policy', exact: true })).toHaveCount(0)
    await page.screenshot({ path: test.info().outputPath('policy-readonly.png'), fullPage: true })
    await fixtureRoute(page, '**/rest/v1/rpc/shop_cash_policy', route => route.fulfill({ status: 500, json: { message: 'load failed' } }))
    await fixtureReload(page)
    const section = page.locator('section[aria-labelledby="cash-policy-title"]')
    await expect(section.getByRole('alert')).toBeVisible()
    await fixtureUnroute(page, '**/rest/v1/rpc/shop_cash_policy')
    await section.getByRole('button', { name: ar ? 'إعادة المحاولة' : 'Retry', exact: true }).click()
    await expect(toggle).toBeVisible()
    await fixtureRoute(page, '**/rest/v1/rpc/shop_permission_access', route => route.fulfill({ json: { 'settings.manage': true } }))
    await fixtureRoute(page, '**/rest/v1/rpc/set_shop_cash_policy', route => route.fulfill({ status: 403, json: { message: 'SHOP_PERMISSION_DENIED' } }))
    await fixtureReload(page)
    await toggle.check()
    await section.getByRole('button', { name: ar ? 'حفظ سياسة الخزنة' : 'Save cashier policy', exact: true }).click()
    await expect(section.getByRole('alert')).toContainText(ar ? 'مقدرناش نحفظ' : 'Could not save')
  })

  test(`POS policy rejection and Cashier shifts recovery ${locale}`, async ({ page }) => {
    let opened = false
    const { calls } = await pilotFixture(page, locale, 'owner', name => {
      if (name === 'cash_shift_dashboard') return { canManage: true, canAdjust: true, currentMembershipId: 'membership-1', active: opened ? { id: 'shift-1', cashierMembershipId: 'membership-1', cashierName: 'Pilot barber', registerKey: 'main', openedAt: new Date().toISOString(), openingAmount: 0, expectedCash: 0, cashSales: 0, cashRefunds: 0, payIns: 0, payOuts: 0, nonCashTotal: 0, nonCashByMethod: {}, events: [] } : null, items: [], total: 0, cashiers: [] }
      if (name === 'open_cash_shift') { opened = true; return 'shift-1' }
      return undefined
    })
    await fixtureRoute(page, '**/rest/v1/rpc/checkout_pos_sale', async route => {
      if (!opened) await route.fulfill({ status: 400, json: { message: 'SALE_OPEN_CASH_SHIFT_REQUIRED' } })
      else await route.fallback()
    })
    await fixtureGoto(page, '/pos')
    await page.getByRole('button', { name: /Haircut/ }).click()
    await page.keyboard.press('F8')
    await page.getByRole('dialog').getByRole('button', { name: ar ? 'تأكيد' : 'Confirm', exact: true }).click()
    await expect(page.getByRole('alert')).toContainText(ar ? 'ورديات الخزنة' : 'Cashier shifts')
    await expect(page).toHaveURL(/\/pos$/)
    await page.screenshot({ path: test.info().outputPath('checkout-blocked.png'), fullPage: true })
    await fixtureGoto(page, '/cash-shifts')
    await page.getByRole('button', { name: ar ? 'فتح وردية' : 'Open shift', exact: true }).click()
    await page.getByRole('dialog').getByRole('button', { name: ar ? 'فتح الخزنة' : 'Open drawer', exact: true }).click()
    await page.getByRole('dialog', { name: ar ? 'تأكيد' : 'Confirm', exact: true }).getByRole('button', { name: ar ? 'تأكيد' : 'Confirm', exact: true }).click()
    await expect(page.getByRole('dialog')).toHaveCount(0)
    expect(opened).toBe(true)
    await fixtureGoto(page, '/pos')
    await page.getByRole('button', { name: /Haircut/ }).click()
    await page.keyboard.press('F8')
    await page.getByRole('dialog').getByRole('button', { name: ar ? 'تأكيد' : 'Confirm', exact: true }).click()
    await expect(page).toHaveURL(/\/receipt\?origin=pos/)
    expect(calls.some(call => call.name === 'open_cash_shift')).toBe(true)
    expect(calls.filter(call => call.name === 'checkout_pos_sale')).toHaveLength(1)
  })
  test(`Sales draft saving, issue and payment policy errors ${locale}`, async ({ page }) => {
    const sale = {
      id: 'sale-1', invoice_number: null, status: 'draft', created_at: new Date().toISOString(), issued_at: null,
      total_amount: 100, discount_amount: 0, notes: '', client_id: 'customer-1', client_name_snapshot: 'Policy customer',
      due_date: null, amountPaid: 0, outstanding: 100, settlementState: 'unpaid', overdue: false,
      canManage: true, canIssue: true, canReceivePayment: true, canReversePayment: false, canRefundPayment: false,
      lines: [{ id: 'line-1', item_type: 'service', item_name: 'Haircut', quantity: 1, unit_price: 100,
        discount_amount: 0, total_amount: 100, product_id: null, service_id: 'service-1' }], movements: [], payments: [],
    }
    const { calls } = await pilotFixture(page, locale, 'owner', name => {
      if (name === 'get_sale' || name === 'get_location_sale') return sale
      if (name === 'sale_access') return [{ can_view: true, can_manage: true, can_issue: true }]
      if (name === 'payment_access') return [{ can_receive: true }]
      if (name === 'list_location_sales') return { items: [], total: 0, canManage: true, canIssue: true }
      if (name === 'sale_catalog') return { businessMode: 'service', products: [], services: [{ id: 'service-1', name: 'Haircut', unitPrice: 100, discountType: 'amount', discountValue: 0 }], customers: [{ id: 'customer-1', name: 'Policy customer' }] }
      if (name === 'save_location_sale_draft') return 'sale-1'
      if (name === 'get_location_sale_receipt') return null
      if (name === 'sale_correction_state') return { canCorrect: false, correction: null }
      return undefined
    })
    for (const name of ['issue_location_sale', 'checkout_location_sale', 'record_location_customer_receipt']) {
      await fixtureRoute(page, `**/rest/v1/rpc/${name}`, route => route.fulfill({ status: 400, json: { message: 'SALE_OPEN_CASH_SHIFT_REQUIRED' } }))
    }
    // Existing customer draft can be edited and saved despite no open shift.
    await fixtureGoto(page, '/sales?edit=sale-1')
    await page.getByRole('dialog').getByRole('button', { name: ar ? 'حفظ المسودة' : 'Save draft', exact: true }).click()
    await expect(page.getByRole('dialog')).toHaveCount(0)
    expect(calls.some(call => call.name === 'save_location_sale_draft')).toBe(true)
    await fixtureGoto(page, '/sales/sale-1')
    await page.getByRole('button', { name: ar ? 'إصدار البيعة' : 'Issue sale', exact: true }).click()
    await page.getByRole('dialog').getByRole('button', { name: ar ? 'تأكيد' : 'Confirm', exact: true }).click()
    await expect(page.getByRole('alert')).toContainText(ar ? 'ورديات الخزنة' : 'Cashier shifts')
    await page.screenshot({ path: test.info().outputPath('sale-issue-blocked.png'), fullPage: true })
    sale.status = 'issued'
    await fixtureReload(page)
    await page.getByRole('button', { name: ar ? 'تسجيل تحصيل' : 'Record receipt', exact: true }).click()
    await page.getByRole('dialog').getByRole('button', { name: ar ? 'حفظ' : 'Save', exact: true }).click()
    await expect(page.getByRole('dialog').getByRole('alert')).toContainText(ar ? 'ورديات الخزنة' : 'Cashier shifts')
    await page.screenshot({ path: test.info().outputPath('sale-payment-blocked.png'), fullPage: true })
    // Customerless issue-and-take-payment (the fast checkout path).
    sale.status = 'draft'; sale.client_id = ''
    await fixtureGoto(page, '/sales?edit=sale-1')
    await page.getByRole('dialog').getByRole('button', { name: ar ? 'إصدار وتحصيل المبلغ' : 'Issue and take payment', exact: true }).click()
    await page.getByRole('dialog').filter({ hasText: ar ? 'تأكيد' : 'Confirm' }).getByRole('button', { name: ar ? 'تأكيد' : 'Confirm', exact: true }).click()
    await expect(page.getByRole('dialog').getByRole('alert')).toContainText(ar ? 'ورديات الخزنة' : 'Cashier shifts')
  })

}
